// SmartForm preview baseline on the SAP sample ref set (S4-DEV content): raw interface values → preview values
// (valuesFromRaw), sums the form's program lines compute (simple statements only, run per loop row), build with
// --layout-json, score against SAP's PDF. usage: node sfsample-baseline-d.mjs <outDir> [--set ref|heldout]
// D (2026-11-18): a loop / table with sort events runs its program lines per group — the sort-begin event's code at each
// group start, the body per row, the sort-end event's code at the group end — and a table printed in the sort-end
// event is kept per group (values: one array per group, build-preview takes the group's rows)
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
const SC = 'C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap/scripts';
const NOTES = 'C:/Users/pssps/Documents/Projects/sc4sap_project/notes';
const { valuesFromRaw } = await import(`file:///${SC}/smartform/preview-values.mjs`);
const { runInitCoding } = await import(`file:///${SC}/adobe/adobe-data.mjs`);
const { scoreFidelity, scoreCorpus } = await import(`file:///${SC}/forms-common/score-fidelity.mjs`);
const out = process.argv[2];
const set = process.argv.includes('--set') ? process.argv[process.argv.indexOf('--set') + 1] : 'ref';
const REF = `${NOTES}/form-fidelity/${set}`;
const CORP = `${NOTES}/adobe-2026-11-17/corpus/smartform-preview`;
const m = JSON.parse(readFileSync(`${REF}/manifest.json`, 'utf8'));
const results = [];
for (const [id, e] of Object.entries(m)) {
  if (e.kind !== 'sf') continue;
  const cdir = join(CORP, existsSync(join(CORP, id)) ? id : Object.keys(m).find((k) => m[k].form === e.form && existsSync(join(CORP, k))) || id);
  const f = e.form.toLowerCase();
  const contentF = join(cdir, `${f}.content.json`), xmlF = join(cdir, `${f}.xml`);
  if (!existsSync(contentF)) { console.log(id, 'no content'); continue; }
  const content = JSON.parse(readFileSync(contentF, 'utf8'));
  const raw = JSON.parse(readFileSync(join(REF, e.values), 'utf8'));
  const ddicF = join(`${NOTES}/form-fidelity/ref/ddic`, `${id}.ddic.json`);
  const ddic = existsSync(ddicF) ? JSON.parse(readFileSync(ddicF, 'utf8')).ddic || {} : {};
  // program lines (from the form XML), run per row of the loop / table they sit in
  const notes = [];
  if (existsSync(xmlF)) {
    const xml = readFileSync(xmlF, 'utf8');
    const code = {};
    for (const mm of xml.matchAll(/<sf:CODE>[\s\S]*?<\/sf:CODE>/g)) {
      const name = (/<INAME>([^<]+)<\/INAME>/.exec(mm[0]) || [])[1];
      code[name] = [...mm[0].matchAll(/<item>([^<]*)<\/item>/g)].map((x) => x[1].replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&apos;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&'));
    }
    // program lines in processing order: a loop / table runs its header events once, its body per row, its footer
    // events once (the work area = the last row); globals carry over (state)
    let state = { tables: {}, vars: {} };
    const tables = state.tables;
    const perGroup = {}; // table → [rows of group 0, rows of group 1, …]
    const run = (n, prefix = [], suffix = []) => {
      const r = runInitCoding([...prefix, ...code[n.name], ...suffix], { ...raw, ...state.tables }, ddic, state);
      if (r.ok) state = { tables: r.tables, vars: r.vars }; else notes.push(`${n.name}: ${r.reason}`);
    };
    const codes = (list) => { const o = []; const w = (l) => { for (const n of l || []) { if (n.kind === 'code' && code[n.name]) o.push(n); w(n.children); } }; w(list); return o; };
    // a node's simple conditions (EQ / NE on a scalar interface value): a table the form skips runs no code
    const condOk = (n) => (n.condition?.COND || []).every((c) => {
      const a = String(raw[String(c.OP1 || '').toUpperCase()] ?? raw[c.OP1] ?? '').trim();
      const b = String(c.OP2 ?? '').replace(/^'|'$/g, '').trim();
      return c.COP === 'EQ' ? a === b : c.COP === 'NE' ? a !== b : true;
    });
    const walk = (list) => {
      for (const n of list || []) {
        if (!condOk(n)) continue;
        const loop = n.dataTable && n.attrs?.TABHEADER;
        if (loop) {
          const ev = (t) => (n.children || []).filter((c) => c.kind === 'event' && c.attrs?.EVTYPE === t);
          for (const e of ev('H')) for (const c of codes(e.children)) run(c);
          const sortS = ev('S').filter((e) => e.attrs?.SFIELD), sortE = ev('E').filter((e) => e.attrs?.SFIELD);
          if (sortS.length || sortE.length) {
            const wa = String(n.attrs.TABHEADER).toUpperCase();
            const sf = String((sortS[0] || sortE[0]).attrs.SFIELD).toUpperCase();
            let rows0 = ((Array.isArray(raw[n.dataTable]) ? raw[n.dataTable] : state.tables[String(n.dataTable).toUpperCase()]) || []).slice();
            const val = (r) => String(Object.entries(r).find(([k]) => k.toUpperCase() === sf)?.[1] ?? '');
            // build-preview sorts a new table / loop by the sort field, an old (4.6) table keeps the order
            if (n.kind !== 'table46') rows0 = rows0.map((r, i) => [r, i]).sort((a, b) => val(a[0]).localeCompare(val(b[0])) || a[1] - b[1]).map((x) => x[0]);
            const groups = [];
            for (const r of rows0) { const g = groups[groups.length - 1]; if (g && val(g[0]) === val(r)) g.push(r); else groups.push([r]); }
            const body = (n.children || []).filter((c) => c.kind !== 'event' || c.attrs?.EVTYPE === 'B');
            const bodyCodes = codes(body);
            const printedInE = []; const wE = (l) => { for (const x of l || []) { if (x.dataTable && !printedInE.includes(String(x.dataTable).toUpperCase())) printedInE.push(String(x.dataTable).toUpperCase()); wE(x.children); } };
            for (const e of sortE) wE(e.children);
            const asWa = (r) => Object.fromEntries(Object.entries(r).map(([a, b]) => [a.toUpperCase(), b]));
            for (const g of groups) {
              state.vars[wa] = asWa(g[0]);
              for (const e of sortS) for (const c of codes(e.children)) run(c);
              if (bodyCodes.length) {
                const tmp = '__GROUP_ROWS';
                const lines = [`loop at ${tmp} into ${n.attrs.TABHEADER}.`, ...bodyCodes.flatMap((c) => code[c.name]), 'endloop.'];
                const r = runInitCoding(lines, { ...raw, ...state.tables, [tmp]: g }, ddic, state);
                if (r.ok) { delete r.tables[tmp]; delete r.tables[tmp.toUpperCase()]; state = { tables: r.tables, vars: r.vars }; } else notes.push(`${bodyCodes.map((c) => c.name).join('+')}: ${r.reason}`);
              }
              state.vars[wa] = asWa(g[g.length - 1]);
              for (const e of sortE) for (const c of codes(e.children)) run(c);
              for (const t of printedInE) (perGroup[t] ||= []).push((state.tables[t] || []).map((x) => ({ ...x })));
            }
            for (const e of ev('F')) for (const c of codes(e.children)) run(c);
            continue;
          }
          const body = (n.children || []).filter((c) => c.kind !== 'event' || c.attrs?.EVTYPE === 'B');
          const bodyCodes = codes(body);
          const rows = (Array.isArray(raw[n.dataTable]) ? raw[n.dataTable] : state.tables[String(n.dataTable).toUpperCase()]) || [];
          if (bodyCodes.length) for (const c of bodyCodes) { /* one LOOP per code node, in order, rows interleaved below */ }
          if (bodyCodes.length) {
            // every row runs all body code nodes in order
            const lines = [`loop at ${n.dataTable} into ${n.attrs.TABHEADER}.`, ...bodyCodes.flatMap((c) => code[c.name]), 'endloop.'];
            const r = runInitCoding(lines, { ...raw, ...state.tables }, ddic, state);
            if (r.ok) state = { tables: r.tables, vars: r.vars }; else notes.push(`${bodyCodes.map((c) => c.name).join('+')}: ${r.reason}`);
          }
          // the footer sees the last row in the work area
          const last = rows[rows.length - 1];
          if (last) state.vars[String(n.attrs.TABHEADER).toUpperCase()] = Object.fromEntries(Object.entries(last).map(([a, b]) => [a.toUpperCase(), b]));
          for (const e of ev('F')) for (const c of codes(e.children)) run(c);
          continue;
        }
        if (n.kind === 'code' && code[n.name]) run(n);
        walk(n.children);
      }
    };
    for (const p of content.pages) for (const w of p.windows) walk(w.content);
    Object.assign(tables, state.tables);
    raw.__perGroup = perGroup;
    for (const [t, rows] of Object.entries(tables)) {
      raw[t] = rows;
      // field types of a computed table: from a table field of the same name
      for (const fld of Object.keys(rows[0] || {})) {
        const k = Object.keys(ddic).find((x) => x.toUpperCase().endsWith(`-${fld}`));
        if (k && !ddic[`${t}-${fld}`]) ddic[`${t}-${fld}`] = ddic[k];
      }
    }
  }
  const perGroup = raw.__perGroup || {};
  delete raw.__perGroup;
  const { values, rows } = valuesFromRaw(content, raw, { ddic });
  // tables printed in a sort-end event: one array of rows per group (build-preview: the group's own rows)
  for (const [t, groups] of Object.entries(perGroup)) {
    const per = groups.map((g) => valuesFromRaw(content, { [t]: g }, { ddic }).values);
    const keys = new Set(per.flatMap((v) => Object.keys(v)));
    for (const k of keys) values[k] = per.map((v) => v[k] || []);
  }
  // the date SAP prints for SY-DATUM / SFSY-DATE: the render day, in the user's format
  const day = String(e.at || '').slice(0, 10).split('-');
  if (day.length === 3) values['SY-DATUM'] = values['SFSY-DATE'] = `${day[1]}/${day[2]}/${day[0]}`;
  const od = join(out, id);
  mkdirSync(od, { recursive: true });
  // graphics only from the content folder: a copy with its graphics next to it
  const cd = join(od, 'content');
  mkdirSync(cd, { recursive: true });
  for (const g of content.graphics || []) if (g.file) { const b = g.file.split(/[\\/]/).pop(); if (existsSync(join(cdir, b))) { writeFileSync(join(cd, b), readFileSync(join(cdir, b))); g.file = join(process.cwd(), cd, b); } }
  writeFileSync(join(cd, `${f}.content.json`), JSON.stringify(content));
  writeFileSync(join(od, 'values.json'), JSON.stringify({ values, rows: rows || 1 }, null, 1));
  try {
    execFileSync('node', [`${SC}/smartform/build-preview.mjs`, 'build', join(cd, `${f}.content.json`), '--values', join(od, 'values.json'), '--out-dir', od, '--no-jpg', '--layout-json'], { stdio: ['ignore', 'pipe', 'pipe'], timeout: 180000 });
    const lay = readdirSync(od).find((x) => x.endsWith('-preview.layout.json'));
    const r = scoreFidelity(readFileSync(join(REF, e.files.pdf.file)), JSON.parse(readFileSync(join(od, lay), 'utf8')));
    writeFileSync(join(od, 'fidelity.json'), JSON.stringify(r, null, 1));
    results.push({ name: id, ...r });
    console.log(id, r.percent, 'text', r.textPercent, r.pagesMismatch ? 'PAGES' : '', JSON.stringify(r.counts), notes.join('; '));
  } catch (err) { results.push({ name: id, score: null, error: String(err.message || err).slice(0, 200) }); console.log(id, 'ERROR', String(err.message || err).slice(0, 200)); }
}
const c = scoreCorpus(results);
console.log('CORPUS', c.averagePercent, 'text', c.textAveragePercent, 'pagesMismatch', c.pagesMismatch.length);
