    for (const p of content.pages) for (const w of p.windows) walk(w.content);
    Object.assign(tables, state.tables);
    raw.__perGroup = perGroup;
    for (const [t, rows] of Object.entries(tables)) {
      raw[t] = rows;
      // field types of a computed table: from a table field of the same name
      for (const fld of Object.keys(rows[0] || {})) {
        const k = Object.keys(ddic).find((x) => x.toUpperCase().endsWith(`-${fld}`));
        if (k && !ddic[`${t}-${fld}`]) ddic[`${t}-${fld}`] = ddic[k];
      }
    }
  }
  const perGroup = raw.__perGroup || {};
  delete raw.__perGroup;
  const { values, rows } = valuesFromRaw(content, raw, { ddic });
  // tables printed in a sort-end event: one array of rows per group (build-preview: the group's own rows)
  for (const [t, groups] of Object.entries(perGroup)) {
    const per = groups.map((g) => valuesFromRaw(content, { [t]: g }, { ddic }).values);
    const keys = new Set(per.flatMap((v) => Object.keys(v)));
    for (const k of keys) values[k] = per.map((v) => v[k] || []);
  }
  // the date SAP prints for SY-DATUM / SFSY-DATE: the render day, in the user's format
  const day = String(e.at || '').slice(0, 10).split('-');
  if (day.length === 3) values['SY-DATUM'] = values['SFSY-DATE'] = `${day[1]}/${day[2]}/${day[0]}`;
  const od = join(out, id);
  mkdirSync(od, { recursive: true });
  // graphics only from the content folder: a copy with its graphics next to it
  const cd = join(od, 'content');
  mkdirSync(cd, { recursive: true });
  for (const g of content.graphics || []) if (g.file) { const b = g.file.split(/[\\/]/).pop(); if (existsSync(join(cdir, b))) { writeFileSync(join(cd, b), readFileSync(join(cdir, b))); g.file = join(process.cwd(), cd, b); } }
  writeFileSync(join(cd, `${f}.content.json`), JSON.stringify(content));
  writeFileSync(join(od, 'values.json'), JSON.stringify({ values, rows: rows || 1 }, null, 1));
  try {
    execFileSync('node', [`${SC}/smartform/build-preview.mjs`, 'build', join(cd, `${f}.content.json`), '--values', join(od, 'values.json'), '--out-dir', od, '--no-jpg', '--layout-json'], { stdio: ['ignore', 'pipe', 'pipe'], timeout: 180000 });
    const lay = readdirSync(od).find((x) => x.endsWith('-preview.layout.json'));
    const r = scoreFidelity(readFileSync(join(REF, e.files.pdf.file)), JSON.parse(readFileSync(join(od, lay), 'utf8')));
    writeFileSync(join(od, 'fidelity.json'), JSON.stringify(r, null, 1));
    results.push({ name: id, ...r });
    console.log(id, r.percent, 'text', r.textPercent, r.pagesMismatch ? 'PAGES' : '', JSON.stringify(r.counts), notes.join('; '));
  } catch (err) { results.push({ name: id, score: null, error: String(err.message || err).slice(0, 200) }); console.log(id, 'ERROR', String(err.message || err).slice(0, 200)); }
}
const c = scoreCorpus(results);
console.log('CORPUS', c.averagePercent, 'text', c.textAveragePercent, 'pagesMismatch', c.pagesMismatch.length);
