2	// gets, turned into the "as printed" values the preview takes, so a preview and SAP's print of the same data can be
3	// compared. No SAP call.
4	//
5	//   valuesFromRaw(content, raw, { ddic, dateFormat, decimal, group }) → { values, rows }
6	//     content  GetSmartFormContent's content.json (loops / tables: data table and work area)
7	//     raw      interface values: { PARAM: scalar | { FIELD } | [ { FIELD } ] } (globals too, e.g. sums)
8	//     ddic     { "PARAM-FIELD": { type, length, decimals, signed? } } (types decide the printed form; signed = the
9	//              domain sign flag, DD01L SIGNFLAG, where it was read: false → no sign place)
10	//     dateFormat  the print user's date format: 'MM/DD/YYYY' (default), 'DD.MM.YYYY', 'YYYY/MM/DD', 'YYYY.MM.DD' …
11	//
12	// Output: structures as "PARAM-FIELD", table rows as "WA-FIELD": [row values] for the work area the form loops into
13	// (and "TABLE-FIELD" too), rows = the longest table. Dates DATS → the date format, times TIMS → HH:MM:SS,
14	// CURR / DEC / QUAN → grouped with the DDIC decimals (CURR: the currency's decimals when a key field is given),
15	// NUMC / CHAR / others as given.
16	
17	const up = (s) => String(s ?? '').trim().toUpperCase();
18	const CUR_DEC = { JPY: 0, KRW: 0, VND: 0, IDR: 0, CLP: 0, ISK: 0, HUF: 2, KWD: 3, BHD: 3, JOD: 3, OMR: 3, TND: 3 };
19	
20	function fmtDate(v, f) {
21	  const s = String(v ?? '').replace(/\D/g, '');
22	  if (!/^\d{8}$/.test(s) || /^0+$/.test(s)) return String(v ?? '');
23	  const Y = s.slice(0, 4), M = s.slice(4, 6), D = s.slice(6, 8);
24	  return f.replace('YYYY', Y).replace('MM', M).replace('DD', D);
25	}
26	
27	function fmtTime(v) {
28	  const s = String(v ?? '').replace(/\D/g, '');
29	  return /^\d{6}$/.test(s) ? `${s.slice(0, 2)}:${s.slice(2, 4)}:${s.slice(4, 6)}` : String(v ?? '');
30	}
31	
32	function fmtNum(v, dec, { decimal = '.', group = ',', signed } = {}) {
33	  const n = Number(v);
34	  if (!Number.isFinite(n)) return String(v ?? '');
35	  const [ip, fp] = Math.abs(n).toFixed(dec).split('.');
36	  const g = ip.replace(/\B(?=(\d{3})+(?!\d))/g, group);
37	  // SAP writes the minus sign after the number, a positive number keeps that place as a blank (a right-aligned
38	  // amount ends one character short of the cell: SF_SUBTOTALS / SF_TOTALS on S4-DEV, build-preview R60) — only for a
39	  // signed type: a domain without the sign flag (signed: false) has no sign place; unknown → the place is kept
40	  if (signed === false) return `${g}${fp ? decimal + fp : ''}`;
41	  return `${g}${fp ? decimal + fp : ''}${n < 0 ? '-' : ' '}`;
42	}
43	
44	/** Work areas the form's loops and tables use for each data table (TABLE → [WA …]). */
45	function workAreas(content) {
46	  const map = {};
47	  const walk = (list) => {
48	    for (const n of list || []) {
49	      const t = up(n.dataTable), wa = up(n.attrs?.TABHEADER);
50	      if (t && wa) (map[t] ||= new Set()).add(wa);
51	      walk(n.children);
52	    }
53	  };
54	  for (const p of content?.pages || []) for (const w of p.windows || []) walk(w.content);
55	  return Object.fromEntries(Object.entries(map).map(([k, v]) => [k, [...v]]));
56	}
57	
58	export function valuesFromRaw(content, raw = {}, { ddic = {}, dateFormat = 'MM/DD/YYYY', decimal = '.', group = ',' } = {}) {
59	  const dd = {};
60	  for (const [k, v] of Object.entries(ddic || {})) dd[up(k)] = v;
61	  const was = workAreas(content);
62	  const values = {};
63	  let rows = 0;
64	  const fmt = (param, field, v, rec) => {
65	    const t = dd[`${param}-${field}`];
66	    const type = up(t?.type);
67	    if (v === null || v === undefined) return '';
68	    if (type === 'DATS') return fmtDate(v, dateFormat);
69	    if (type === 'TIMS') return fmtTime(v);
70	    if (/^(CURR|DEC|QUAN|FLTP|P)$/.test(type)) {
71	      let dec = Number(t?.decimals ?? 2);
72	      if (type === 'CURR') {
73	        // the currency key of the row (a CUKY field of the same structure) decides the decimals
74	        const key = Object.entries(rec || {}).find(([f]) => up(dd[`${param}-${up(f)}`]?.type) === 'CUKY')?.[1];
75	        if (key !== undefined && CUR_DEC[up(key)] !== undefined) dec = CUR_DEC[up(key)];
76	      }
77	      return fmtNum(v, dec, { decimal, group, signed: t?.signed });
78	    }
79	    if (/^(INT1|INT2|INT4|INT8)$/.test(type)) return String(Math.round(Number(v)));
80	    return String(v);
81	  };
82	  // deep structures are walked: a structure field that is itself a structure or a table becomes "P-F-…" (a deep
83	  // interface like LB_BIL_INVOICE's IS_BIL_INVOICE: &IS_BIL_INVOICE-HD_GEN-BIL_NUMBER&, a loop over
84	  // IS_BIL_INVOICE-IT_GEN into GS_IT_GEN); DDIC keys follow the same path
85	  const put = (P, v) => {
86	    if (Array.isArray(v)) {
87	      rows = Math.max(rows, v.length);
88	      const fields = [...new Set(v.flatMap((r) => (r && typeof r === 'object' ? Object.keys(r).map(up) : [])))];
89	      for (const f of fields) {
90	        const col = v.map((r) => { const e = Object.entries(r || {}).find(([x]) => up(x) === f); return e?.[1] !== null && typeof e?.[1] === 'object' ? '' : fmt(P, f, e?.[1], r); });
91	        values[`${P}-${f}`] = col;
92	        for (const wa of was[P] || []) values[`${wa}-${f}`] = col;
93	      }
94	    } else if (v && typeof v === 'object') {
95	      for (const [f, x] of Object.entries(v)) {
96	        if (x !== null && typeof x === 'object') put(`${P}-${up(f)}`, x);
97	        else values[`${P}-${up(f)}`] = fmt(P, up(f), x, v);
98	      }
99	    } else values[P] = fmt(P, '', v, null);
100	  };
101	  for (const [k, v] of Object.entries(raw || {})) put(up(k), v);
102	  return { values, rows };
103	}
