        for (const wa of was[P] || []) values[`${wa}-${f}`] = col;
      }
    } else if (v && typeof v === 'object') {
      for (const [f, x] of Object.entries(v)) {
        if (x !== null && typeof x === 'object') put(`${P}-${up(f)}`, x);
        else values[`${P}-${up(f)}`] = fmt(P, up(f), x, v);
      }
    } else values[P] = fmt(P, '', v, null);
  };
